// Package auditchain — unit tests for chainEnqueuer.
package auditchain

import (
	"bytes"
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/stretchr/testify/require"

	shelldb "github.com/zenithflowinc/omnicore-platform/services/shell-bff/internal/db"
)

// ---------------------------------------------------------------------------
// fakeDBTX — satisfies shelldb.DBTX without touching Postgres.
// We need to exercise chainEnqueuer.Enqueue, which uses shelldb.Queries
// (a *Queries wrapping a DBTX). We pass a fakeDBTX to shelldb.New(…) in
// newFakeChainEnqueuer so the Queries struct is real but dispatches to our
// fake.
// ---------------------------------------------------------------------------

// fakeDBTX implements shelldb.DBTX via a narrow recording shim.
// Each query is matched by the query string prefix so fakes can intercept
// LatestEntryHash and EnqueueAuditEvent independently.
type fakeDBTX struct {
	// latestHash is returned by QueryRow when "SELECT entry_hash" is called.
	// nil → empty table (pgx.ErrNoRows returned from Scan).
	latestHash []byte
	latestErr  error // if non-nil, Scan returns this error instead

	// enqueueErr is returned by QueryRow when "INSERT INTO shell_bff" is called.
	enqueueErr error

	// captured is populated when EnqueueAuditEvent executes successfully.
	captured *shelldb.EnqueueAuditEventParams
}

// --- pgx.Row adapters -------------------------------------------------------

type fakeRow struct {
	scanFn func(dest ...any) error
}

func (r *fakeRow) Scan(dest ...any) error { return r.scanFn(dest...) }

// --- pgconn shim ------------------------------------------------------------

// pgconn.CommandTag is a value type; we return zero value from Exec.

// QueryRow dispatches to either the LatestEntryHash or EnqueueAuditEvent
// branch depending on which SQL constant the Queries struct is executing.
// The sqlc-generated constants are multi-line raw strings starting with
// "-- name: <QueryName>". We match by inspecting the name comment.
func (f *fakeDBTX) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	// LatestEntryHash — comment contains "LatestEntryHash"
	if strings.Contains(sql, "LatestEntryHash") {
		if f.latestErr != nil {
			return &fakeRow{scanFn: func(dest ...any) error { return f.latestErr }}
		}
		if f.latestHash == nil {
			return &fakeRow{scanFn: func(dest ...any) error { return pgx.ErrNoRows }}
		}
		return &fakeRow{scanFn: func(dest ...any) error {
			if len(dest) == 0 {
				return nil
			}
			ptr, ok := dest[0].(*[]byte)
			if !ok {
				return errors.New("fakeDBTX: expected *[]byte for entry_hash")
			}
			*ptr = f.latestHash
			return nil
		}}
	}

	// EnqueueAuditEvent — "INSERT INTO shell_bff"
	if f.enqueueErr != nil {
		return &fakeRow{scanFn: func(dest ...any) error { return f.enqueueErr }}
	}
	// Parse the args back to capture the params for assertion.
	if len(args) >= 8 {
		actorUserID, _ := args[1].(uuid.UUID)
		var actorOrgID *uuid.UUID
		if v, ok := args[2].(*uuid.UUID); ok {
			actorOrgID = v
		}
		var targetOrgID *uuid.UUID
		if v, ok := args[3].(*uuid.UUID); ok {
			targetOrgID = v
		}
		requestID, _ := args[4].(string)
		payload, _ := args[5].([]byte)
		prevHash, _ := args[6].([]byte)
		entryHash, _ := args[7].([]byte)
		f.captured = &shelldb.EnqueueAuditEventParams{
			EventType:   "auth.session_tenant_switched",
			ActorUserID: actorUserID,
			ActorOrgID:  actorOrgID,
			TargetOrgID: targetOrgID,
			RequestID:   requestID,
			Payload:     payload,
			PrevHash:    prevHash,
			EntryHash:   entryHash,
		}
	}
	// Return a successful row scan (the function returns ShellBffAuditOutbox).
	row := shelldb.ShellBffAuditOutbox{
		ID: uuid.New(),
	}
	return &fakeRow{scanFn: func(dest ...any) error {
		if len(dest) < 11 {
			return nil
		}
		if p, ok := dest[0].(*uuid.UUID); ok {
			*p = row.ID
		}
		return nil
	}}
}

func (f *fakeDBTX) Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error) {
	return nil, nil
}

func (f *fakeDBTX) Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error) {
	return pgconn.CommandTag{}, nil
}

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

func newFakeChainEnqueuer(t *testing.T, fake *fakeDBTX, key []byte, keyID string) AuditEnqueuer {
	t.Helper()
	// chainEnqueuer is unexported; we access it through NewChainEnqueuer which
	// accepts a pgx.Tx. pgx.Tx embeds DBTX, so we use fakeTx to satisfy it.
	ft := &fakeTx{fakeDBTX: fake}
	enqueuer, err := NewChainEnqueuer(context.Background(), ft, key, keyID)
	require.NoError(t, err)
	return enqueuer
}

// fakeTx wraps fakeDBTX and satisfies the pgx.Tx interface (which is large;
// we only need the DBTX subset that shelldb.Queries actually calls).
// All other pgx.Tx methods panic — they should never be called by the enqueuer.
type fakeTx struct {
	*fakeDBTX
}

// pgx.Tx requires several additional methods. We satisfy them with stubs.
func (f *fakeTx) Begin(ctx context.Context) (pgx.Tx, error) { panic("not called") }
func (f *fakeTx) Commit(ctx context.Context) error          { panic("not called") }
func (f *fakeTx) Rollback(ctx context.Context) error        { panic("not called") }
func (f *fakeTx) CopyFrom(ctx context.Context, tableName pgx.Identifier, columnNames []string, rowSrc pgx.CopyFromSource) (int64, error) {
	panic("not called")
}
func (f *fakeTx) SendBatch(ctx context.Context, b *pgx.Batch) pgx.BatchResults { panic("not called") }
func (f *fakeTx) LargeObjects() pgx.LargeObjects                               { panic("not called") }
func (f *fakeTx) Prepare(ctx context.Context, name, sql string) (*pgconn.StatementDescription, error) {
	panic("not called")
}
func (f *fakeTx) Conn() *pgx.Conn { panic("not called") }

// ---------------------------------------------------------------------------
// TestNewChainEnqueuer_ReturnsNonNil
// ---------------------------------------------------------------------------

func TestNewChainEnqueuer_ReturnsNonNil(t *testing.T) {
	fake := &fakeDBTX{}
	ft := &fakeTx{fakeDBTX: fake}
	key := []byte("test-hmac-key-at-least-32-bytes!")
	keyID := "key-1"

	enqueuer, err := NewChainEnqueuer(context.Background(), ft, key, keyID)

	require.NoError(t, err)
	require.NotNil(t, enqueuer)
}

func TestNewChainEnqueuer_RejectsEmptyKey(t *testing.T) {
	fake := &fakeDBTX{}
	ft := &fakeTx{fakeDBTX: fake}

	_, err := NewChainEnqueuer(context.Background(), ft, nil, "key-1")

	require.Error(t, err)
}

func TestNewChainEnqueuer_RejectsEmptyKeyID(t *testing.T) {
	fake := &fakeDBTX{}
	ft := &fakeTx{fakeDBTX: fake}

	_, err := NewChainEnqueuer(context.Background(), ft, []byte("key"), "")

	require.Error(t, err)
}

// ---------------------------------------------------------------------------
// TestChainEnqueuer_Enqueue_HappyPath
// ---------------------------------------------------------------------------

// TestChainEnqueuer_Enqueue_HappyPath asserts that when LatestEntryHash
// returns a prev_hash, Enqueue computes the correct HMAC chain and inserts
// with that prev_hash.
func TestChainEnqueuer_Enqueue_HappyPath(t *testing.T) {
	prevHashBytes := bytes.Repeat([]byte{0xaa}, 32)
	fake := &fakeDBTX{latestHash: prevHashBytes}
	key := []byte("test-hmac-key-at-least-32-bytes!")
	e := newFakeChainEnqueuer(t, fake, key, "key-1")

	actorID := uuid.New()
	fromOrg := uuid.New().String()
	toOrg := uuid.New().String()

	err := e.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: actorID.String(),
		ActorOrgID:  &fromOrg,
		TargetOrgID: &toOrg,
		RequestID:   "req-001",
		IP:          "10.0.0.1",
		UserAgent:   "test-agent",
	})

	require.NoError(t, err)
	require.NotNil(t, fake.captured, "EnqueueAuditEvent must have been called")

	// PrevHash must match what LatestEntryHash returned.
	require.Equal(t, prevHashBytes, fake.captured.PrevHash)

	// EntryHash must be non-zero.
	require.NotEmpty(t, fake.captured.EntryHash)
	require.NotEqual(t, make([]byte, 32), fake.captured.EntryHash)

	// EntryHash must equal ComputeHash(key, prevHash, canonical_payload).
	payload := SwitchPayload{
		ActorUserID: actorID.String(),
		FromOrgID:   fromOrg,
		ToOrgID:     toOrg,
		RequestID:   "req-001",
		IP:          "10.0.0.1",
		UserAgent:   "test-agent",
	}
	canonical, err := CanonicalPayload(payload)
	require.NoError(t, err)
	expectedHash := ComputeHash(key, prevHashBytes, canonical)
	require.Equal(t, expectedHash, fake.captured.EntryHash)
}

// ---------------------------------------------------------------------------
// TestChainEnqueuer_Enqueue_FirstRow_UsesGenesisHash
// ---------------------------------------------------------------------------

// TestChainEnqueuer_Enqueue_FirstRow_UsesGenesisHash asserts that when
// LatestEntryHash returns nil (empty table), the genesis sentinel is used.
func TestChainEnqueuer_Enqueue_FirstRow_UsesGenesisHash(t *testing.T) {
	fake := &fakeDBTX{latestHash: nil} // empty table
	key := []byte("test-hmac-key-at-least-32-bytes!")
	e := newFakeChainEnqueuer(t, fake, key, "key-1")

	actorID := uuid.New()

	err := e.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: actorID.String(),
		RequestID:   "req-genesis",
		IP:          "10.0.0.2",
		UserAgent:   "test-ua",
	})

	require.NoError(t, err)
	require.NotNil(t, fake.captured)
	require.Equal(t, GenesisHash, fake.captured.PrevHash)
}

// ---------------------------------------------------------------------------
// TestChainEnqueuer_Enqueue_LatestHashError_Propagates
// ---------------------------------------------------------------------------

// TestChainEnqueuer_Enqueue_LatestHashError_Propagates ensures that a
// non-ErrNoRows error from LatestEntryHash is propagated and no INSERT occurs.
func TestChainEnqueuer_Enqueue_LatestHashError_Propagates(t *testing.T) {
	dbErr := errors.New("connection reset by peer")
	fake := &fakeDBTX{latestErr: dbErr}
	e := newFakeChainEnqueuer(t, fake, []byte("test-hmac-key-at-least-32-bytes!"), "key-1")

	actorID := uuid.New()
	err := e.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: actorID.String(),
		RequestID:   "req-err",
		IP:          "1.1.1.1",
		UserAgent:   "ua",
	})

	require.Error(t, err)
	require.Nil(t, fake.captured, "EnqueueAuditEvent must NOT be called on fetch error")
}

// ---------------------------------------------------------------------------
// TestChainEnqueuer_Enqueue_EnqueueAuditEventError_Propagates
// ---------------------------------------------------------------------------

// TestChainEnqueuer_Enqueue_EnqueueAuditEventError_Propagates ensures that
// an error from EnqueueAuditEvent is propagated.
func TestChainEnqueuer_Enqueue_EnqueueAuditEventError_Propagates(t *testing.T) {
	prevHashBytes := bytes.Repeat([]byte{0xbb}, 32)
	insertErr := errors.New("unique constraint violation")
	fake := &fakeDBTX{latestHash: prevHashBytes, enqueueErr: insertErr}
	e := newFakeChainEnqueuer(t, fake, []byte("test-hmac-key-at-least-32-bytes!"), "key-1")

	actorID := uuid.New()
	err := e.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: actorID.String(),
		RequestID:   "req-insert-err",
		IP:          "2.2.2.2",
		UserAgent:   "ua",
	})

	require.Error(t, err)
}


