// Package auditchain implements the shell-bff audit hash-chain helpers.
//
// Unlike identity-svc and org-svc, which chain proto-encoded AuditEvent
// messages via platform/libs/go/audit.ChainEvent, shell-bff owns a
// bespoke table (shell_bff.audit_outbox) that stores raw BYTEA payloads and
// BYTEA hashes. The hash is:
//
//	entry_hash = HMAC-SHA256(audit_secret, prev_hash_bytes || canonical_payload_bytes)
//
// where canonical_payload_bytes is the UTF-8-encoded JSON produced by
// encoding/json.Marshal (deterministic because the payload struct is
// defined here with fixed field order). This package provides:
//
//   - AuditEnqueuer — the interface the SwitchWorkspace handler depends on
//   - ComputeHash   — the raw HMAC-SHA256 primitive
//   - GenesisHash   — the sentinel 32-zero-byte prev_hash for the first row
package auditchain

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/json"
	"fmt"
)

// GenesisHash is the 32-byte all-zero sentinel used as prev_hash when the
// audit_outbox table is empty and the first row has no predecessor.
var GenesisHash = make([]byte, 32)

// SwitchPayload is the canonical payload struct for event_type
// "auth.session_tenant_switched". Fields are exported and marshalled in
// struct-declaration order by encoding/json (Go struct order is stable).
// Never log the full struct — it contains actor_user_id (a UUID, not
// secret) but the discipline is to keep audit payloads out of log sinks.
type SwitchPayload struct {
	ActorUserID string `json:"actor_user_id"`
	FromOrgID   string `json:"from_org_id"`
	ToOrgID     string `json:"to_org_id"`
	RequestID   string `json:"request_id"`
	IP          string `json:"ip"`
	UserAgent   string `json:"user_agent"`
}

// CanonicalPayload serialises p to deterministic JSON bytes suitable for
// use as the payload column and as the hash input. Returns an error only if
// encoding/json fails, which it cannot for this struct (no channels, funcs,
// or unsupported types).
func CanonicalPayload(p SwitchPayload) ([]byte, error) {
	b, err := json.Marshal(p)
	if err != nil {
		return nil, fmt.Errorf("auditchain: marshal payload: %w", err)
	}
	return b, nil
}

// ComputeHash returns HMAC-SHA256(key, prevHash || payloadBytes).
//
// The key MUST be non-empty; callers should validate before calling.
// prevHash is the raw bytes from the preceding row's entry_hash column
// (or GenesisHash for the very first row). payloadBytes is the output of
// CanonicalPayload.
func ComputeHash(key, prevHash, payloadBytes []byte) []byte {
	h := hmac.New(sha256.New, key)
	h.Write(prevHash)
	h.Write(payloadBytes)
	return h.Sum(nil)
}

// EnqueueParams are the inputs to AuditEnqueuer.Enqueue. Fields map 1:1
// to shell_bff.audit_outbox columns.
//
// Ctx must be set by the caller to the request context so the DB transaction
// inherits the request deadline, trace span, and cancellation signal.
// PoolEnqueuer will error if Ctx is nil; fake implementations in tests may
// ignore Ctx.
type EnqueueParams struct {
	Ctx         context.Context
	ActorUserID string  // UUID string; required
	ActorOrgID  *string // UUID string; nil when the caller has no current org (first switch)
	TargetOrgID *string // UUID string; nil only if org_id could not be parsed (shouldn't happen)
	RequestID   string  // x-request-id header value
	IP          string  // RemoteAddr
	UserAgent   string  // User-Agent header
}

// AuditEnqueuer writes one audit row to shell_bff.audit_outbox inside the
// caller's transaction. The implementation is responsible for:
//
//  1. Fetching the current chain tail (prev_hash) from the DB inside the
//     same tx so prev_hash is serialisable.
//  2. Computing the canonical payload JSON.
//  3. Computing entry_hash = ComputeHash(key, prev_hash, payload).
//  4. Inserting via db.Queries.EnqueueAuditEvent.
//
// The interface is defined here so handlers can depend on it without
// importing the concrete DB implementation, keeping unit tests fast (no
// real Postgres required).
type AuditEnqueuer interface {
	Enqueue(params EnqueueParams) error
}


