package auditchain

import (
	"fmt"

	"github.com/jackc/pgx/v5"

	platformdb "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
)

// PoolEnqueuer is the production AuditEnqueuer. For each Enqueue call it:
//
//  1. Opens a WithTxNoTenant transaction (no GUC — shell_bff.audit_outbox
//     has no tenant scope and is exempt from RLS).
//  2. Constructs a chainEnqueuer bound to that tx.
//  3. Runs chain-hash computation + INSERT.
//  4. Commits.
//
// Tests inject a fake implementation of AuditEnqueuer instead of a
// PoolEnqueuer so they never touch Postgres.
type PoolEnqueuer struct {
	Pool  *platformdb.Pool
	Key   []byte
	KeyID string
}

// Enqueue opens a no-tenant tx, builds a chainEnqueuer, calls Enqueue,
// and commits. params.Ctx is used as the transaction context.
func (p *PoolEnqueuer) Enqueue(params EnqueueParams) error {
	if params.Ctx == nil {
		return fmt.Errorf("auditchain: PoolEnqueuer.Enqueue: params.Ctx is required")
	}
	ctx := params.Ctx

	return p.Pool.WithTxNoTenant(ctx, func(tx pgx.Tx) error {
		enqueuer, err := NewChainEnqueuer(ctx, tx, p.Key, p.KeyID)
		if err != nil {
			return err
		}
		return enqueuer.Enqueue(params)
	})
}


