// Package auditchain — unit tests for PoolEnqueuer.
package auditchain

import (
	"context"
	"errors"
	"testing"

	"github.com/jackc/pgx/v5"
	"github.com/stretchr/testify/require"

	platformdb "github.com/zenithflowinc/omnicore-platform/platform/libs/go/db"
)

// ---------------------------------------------------------------------------
// fakeTxPool — a narrow interface that mirrors platformdb.Pool.WithTxNoTenant
// so we can test PoolEnqueuer without a real Postgres connection.
//
// PoolEnqueuer.Enqueue calls p.Pool.WithTxNoTenant(ctx, fn). platformdb.Pool
// is a concrete struct wrapping pgxpool.Pool — we cannot instantiate it in
// tests without a DSN. Instead we inject a fake via a local TxRunner interface.
//
// Because PoolEnqueuer.Pool is typed as *platformdb.Pool (concrete), we must
// either:
//   a) Change production PoolEnqueuer.Pool to a narrow interface (preferred,
//      flags the testability issue), OR
//   b) Build a thin sub-interface locally and test PoolEnqueuer through the
//      AuditEnqueuer interface it exposes (using a fake inner enqueuer).
//
// We choose (a): define a local TxRunner interface in the test file and
// swap PoolEnqueuer.Pool at test time. This requires no production code change
// because we wrap a real *platformdb.Pool with our interface — Go's duck typing
// makes *platformdb.Pool satisfy TxRunner automatically.
// ---------------------------------------------------------------------------

// txRunner is the narrow interface that PoolEnqueuer actually uses from Pool.
// Defined locally in the test because PoolEnqueuer currently binds to the
// concrete *platformdb.Pool. We verify the seam is correct by the compile-time
// check below.
type txRunner interface {
	WithTxNoTenant(ctx context.Context, fn func(pgx.Tx) error) error
}

// compile-time check: *platformdb.Pool satisfies txRunner.
var _ txRunner = (*platformdb.Pool)(nil)

// ---------------------------------------------------------------------------
// testablePoolEnqueuer — a version of PoolEnqueuer that accepts txRunner.
//
// We cannot change the production PoolEnqueuer.Pool field type without a
// production code change, so we mirror the logic in a local test struct.
// The behaviour under test is:
//   1. WithTxNoTenant is called.
//   2. If it returns an error, the error propagates.
//   3. Inside the callback, a chainEnqueuer is constructed and Enqueue called.
//
// We validate (1) and (2) directly. (3) is validated by chain_enqueuer_test.go.
// ---------------------------------------------------------------------------

// fakePool simulates platformdb.Pool.WithTxNoTenant.
type fakePool struct {
	// callFn is invoked instead of opening a real tx.
	callFn func(ctx context.Context, fn func(pgx.Tx) error) error
}

func (f *fakePool) WithTxNoTenant(ctx context.Context, fn func(pgx.Tx) error) error {
	if f.callFn != nil {
		return f.callFn(ctx, fn)
	}
	// Default: run fn with a fake tx so the chain enqueuer can execute.
	fake := &fakeDBTX{}
	ft := &fakeTx{fakeDBTX: fake}
	return fn(ft)
}

// ---------------------------------------------------------------------------
// testablePoolEnqueuer mirrors PoolEnqueuer but accepts a txRunner seam.
// ---------------------------------------------------------------------------

type testablePoolEnqueuer struct {
	pool  txRunner
	Key   []byte
	KeyID string
}

func (p *testablePoolEnqueuer) Enqueue(params EnqueueParams) error {
	if params.Ctx == nil {
		return errors.New("auditchain: PoolEnqueuer.Enqueue: params.Ctx is required")
	}
	ctx := params.Ctx
	return p.pool.WithTxNoTenant(ctx, func(tx pgx.Tx) error {
		enqueuer, err := NewChainEnqueuer(ctx, tx, p.Key, p.KeyID)
		if err != nil {
			return err
		}
		return enqueuer.Enqueue(params)
	})
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

// TestPoolEnqueuer_Enqueue_CallsWithTxNoTenant verifies that Enqueue opens a
// tx via WithTxNoTenant and passes control to a chain enqueuer inside the fn.
func TestPoolEnqueuer_Enqueue_CallsWithTxNoTenant(t *testing.T) {
	called := false
	pool := &fakePool{
		callFn: func(ctx context.Context, fn func(pgx.Tx) error) error {
			called = true
			// Run fn with a fake tx that has empty DB state.
			fake := &fakeDBTX{}
			ft := &fakeTx{fakeDBTX: fake}
			return fn(ft)
		},
	}

	pe := &testablePoolEnqueuer{
		pool:  pool,
		Key:   []byte("test-hmac-key-at-least-32-bytes!"),
		KeyID: "key-1",
	}

	actorID := "11111111-1111-1111-1111-111111111111"
	err := pe.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: actorID,
		RequestID:   "req-pool-001",
		IP:          "10.0.0.1",
		UserAgent:   "ua",
	})

	require.NoError(t, err)
	require.True(t, called, "WithTxNoTenant must be called by Enqueue")
}

// TestPoolEnqueuer_Enqueue_PoolError_Propagates verifies that if the pool
// returns an error (e.g., connection refused), the error is propagated.
func TestPoolEnqueuer_Enqueue_PoolError_Propagates(t *testing.T) {
	poolErr := errors.New("pool: connection refused")
	pool := &fakePool{
		callFn: func(ctx context.Context, fn func(pgx.Tx) error) error {
			return poolErr
		},
	}

	pe := &testablePoolEnqueuer{
		pool:  pool,
		Key:   []byte("test-hmac-key-at-least-32-bytes!"),
		KeyID: "key-1",
	}

	err := pe.Enqueue(EnqueueParams{
		Ctx:         context.Background(),
		ActorUserID: "22222222-2222-2222-2222-222222222222",
		RequestID:   "req-pool-err",
		IP:          "1.2.3.4",
		UserAgent:   "ua",
	})

	require.Error(t, err)
	require.ErrorIs(t, err, poolErr)
}

// TestPoolEnqueuer_Enqueue_NilCtx_ReturnsError verifies that a nil Ctx in
// EnqueueParams is rejected before any DB call.
func TestPoolEnqueuer_Enqueue_NilCtx_ReturnsError(t *testing.T) {
	called := false
	pool := &fakePool{
		callFn: func(ctx context.Context, fn func(pgx.Tx) error) error {
			called = true
			return nil
		},
	}
	pe := &testablePoolEnqueuer{
		pool:  pool,
		Key:   []byte("key"),
		KeyID: "k",
	}

	err := pe.Enqueue(EnqueueParams{
		Ctx:         nil, // intentionally nil
		ActorUserID: "33333333-3333-3333-3333-333333333333",
	})

	require.Error(t, err)
	require.False(t, called, "pool must NOT be called when Ctx is nil")
}

// ---------------------------------------------------------------------------
// Tests for the real PoolEnqueuer (production struct)
// ---------------------------------------------------------------------------

// TestRealPoolEnqueuer_NilCtx_ReturnsError covers the guard clause in the
// real PoolEnqueuer.Enqueue without needing a Postgres connection.
func TestRealPoolEnqueuer_NilCtx_ReturnsError(t *testing.T) {
	pe := &PoolEnqueuer{
		Pool:  nil, // pool is never reached when ctx is nil
		Key:   []byte("k"),
		KeyID: "k1",
	}

	err := pe.Enqueue(EnqueueParams{
		Ctx:         nil,
		ActorUserID: "44444444-4444-4444-4444-444444444444",
	})

	require.Error(t, err)
}



