// Package auditchain — unit tests for hash computation and genesis sentinel.
package auditchain

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"testing"

	"github.com/stretchr/testify/require"
)

// ---------------------------------------------------------------------------
// TestComputeHash_MatchesManual
// ---------------------------------------------------------------------------

// TestComputeHash_MatchesManual confirms that ComputeHash returns the same
// value as a direct HMAC-SHA256(key, prevHash || payload) invocation.
func TestComputeHash_MatchesManual(t *testing.T) {
	key := []byte("test-key-32-bytes-padded-xxxxxxxx")
	prev := GenesisHash
	payload := []byte(`{"actor_user_id":"u1"}`)

	got := ComputeHash(key, prev, payload)

	// Manual computation.
	h := hmac.New(sha256.New, key)
	h.Write(prev)
	h.Write(payload)
	want := h.Sum(nil)

	require.Equal(t, want, got, "ComputeHash must match manual HMAC-SHA256")
}

// ---------------------------------------------------------------------------
// TestGenesisHash_Is32ZeroBytes
// ---------------------------------------------------------------------------

// TestGenesisHash_Is32ZeroBytes asserts the sentinel is exactly 32 zero bytes.
func TestGenesisHash_Is32ZeroBytes(t *testing.T) {
	require.Len(t, GenesisHash, 32, "GenesisHash must be 32 bytes")
	require.True(t, bytes.Equal(GenesisHash, make([]byte, 32)), "GenesisHash must be all-zero")
}

// ---------------------------------------------------------------------------
// TestHashChain_SecondRowLinksToPrevious
// ---------------------------------------------------------------------------

// TestHashChain_SecondRowLinksToPrevious simulates two consecutive switch
// events and asserts that the second row's prev_hash equals the first row's
// entry_hash.
func TestHashChain_SecondRowLinksToPrevious(t *testing.T) {
	key := []byte("test-key-for-chain-link-checking")
	payload1 := []byte(`{"actor_user_id":"u1","from_org_id":"","to_org_id":"org-1","request_id":"r1","ip":"1.2.3.4","user_agent":"test"}`)
	payload2 := []byte(`{"actor_user_id":"u1","from_org_id":"org-1","to_org_id":"org-2","request_id":"r2","ip":"1.2.3.4","user_agent":"test"}`)

	// Row 1: prev = genesis.
	entryHash1 := ComputeHash(key, GenesisHash, payload1)

	// Row 2: prev = entryHash1.
	entryHash2 := ComputeHash(key, entryHash1, payload2)

	// The verifier would assert entryHash2 != entryHash1 (chain advances).
	require.False(t, bytes.Equal(entryHash1, entryHash2), "consecutive hashes must differ")

	// And that row2's prev matches row1's entry_hash.
	// In the verifier, prev_hash for row2 is stored in the DB. Simulate:
	storedPrevRow2 := entryHash1 // the INSERT writes this value
	recomputed := ComputeHash(key, storedPrevRow2, payload2)
	require.Equal(t, entryHash2, recomputed, "recomputed hash must match stored entry_hash")
}

// ---------------------------------------------------------------------------
// TestCanonicalPayload_FieldOrder
// ---------------------------------------------------------------------------

// TestCanonicalPayload_FieldOrder verifies that CanonicalPayload produces
// consistent JSON with all six expected fields present.
func TestCanonicalPayload_FieldOrder(t *testing.T) {
	p := SwitchPayload{
		ActorUserID: "user-1",
		FromOrgID:   "org-a",
		ToOrgID:     "org-b",
		RequestID:   "req-1",
		IP:          "127.0.0.1",
		UserAgent:   "test-agent",
	}

	b, err := CanonicalPayload(p)
	require.NoError(t, err)
	require.NotEmpty(t, b)

	// Call twice — must produce identical bytes (deterministic).
	b2, _ := CanonicalPayload(p)
	require.Equal(t, b, b2, "CanonicalPayload must be deterministic")

	// Spot-check field presence.
	s := string(b)
	require.Contains(t, s, `"actor_user_id":"user-1"`)
	require.Contains(t, s, `"from_org_id":"org-a"`)
	require.Contains(t, s, `"to_org_id":"org-b"`)
	require.Contains(t, s, `"request_id":"req-1"`)
	require.Contains(t, s, `"ip":"127.0.0.1"`)
	require.Contains(t, s, `"user_agent":"test-agent"`)
}

// ---------------------------------------------------------------------------
// TestCanonicalPayload_ExactByteOrder
// ---------------------------------------------------------------------------

// TestCanonicalPayload_ExactByteOrder pins that CanonicalPayload produces the
// exact expected JSON byte sequence. Because Go struct marshalling is
// declaration-order stable (not map-order), this test will catch any
// accidental field reordering or rename in SwitchPayload.
//
// The expected value was hand-computed from the struct definition:
//
//	{"actor_user_id":"...","from_org_id":"...","to_org_id":"...","request_id":"...","ip":"...","user_agent":"..."}
func TestCanonicalPayload_ExactByteOrder(t *testing.T) {
	p := SwitchPayload{
		ActorUserID: "alpha",
		FromOrgID:   "beta",
		ToOrgID:     "gamma",
		RequestID:   "delta",
		IP:          "epsilon",
		UserAgent:   "zeta",
	}

	b, err := CanonicalPayload(p)
	require.NoError(t, err)

	// Expected bytes are the exact JSON that encoding/json produces for
	// a struct with these field tags in declaration order.
	want := `{"actor_user_id":"alpha","from_org_id":"beta","to_org_id":"gamma","request_id":"delta","ip":"epsilon","user_agent":"zeta"}`
	require.Equal(t, want, string(b),
		"CanonicalPayload must produce fields in struct-declaration order")
}


