package auditchain

import (
	"context"
	"encoding/hex"
	"errors"
	"fmt"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	shelldb "github.com/zenithflowinc/omnicore-platform/services/shell-bff/internal/db"
)

// chainEnqueuer is the production AuditEnqueuer. It is constructed once
// per SwitchWorkspace call and is bound to the transaction opened by that
// call. It is NOT safe for concurrent use from multiple goroutines.
type chainEnqueuer struct {
	ctx   context.Context
	q     *shelldb.Queries
	key   []byte
	keyID string
}

// NewChainEnqueuer returns an AuditEnqueuer that writes to the DB via tx.
//
// key is the HMAC-SHA256 secret (from AUDIT_HMAC_KEYS env var, same as
// identity-svc and org-svc). keyID is the active key identifier stored
// alongside the hash for future rotation. tx must be an open, uncommitted
// pgx.Tx that was opened by the caller for the SwitchWorkspace operation.
//
// The Enqueue method reads the chain tail inside the same tx so the
// prev_hash it uses is serialisable with respect to concurrent switches.
func NewChainEnqueuer(ctx context.Context, tx pgx.Tx, key []byte, keyID string) (AuditEnqueuer, error) {
	if len(key) == 0 {
		return nil, fmt.Errorf("auditchain: HMAC key must be non-empty")
	}
	if keyID == "" {
		return nil, fmt.Errorf("auditchain: key_id must be non-empty")
	}
	return &chainEnqueuer{
		ctx:   ctx,
		q:     shelldb.New(tx),
		key:   key,
		keyID: keyID,
	}, nil
}

// Enqueue fetches the chain tail, computes the hash, and inserts the row.
// All operations run inside the tx passed to NewChainEnqueuer.
func (e *chainEnqueuer) Enqueue(params EnqueueParams) error {
	// 1. Fetch prev_hash from the chain tail (most recent row by created_at).
	// LatestEntryHash's FOR UPDATE locks nothing when the table is empty, so
	// two concurrent first-ever calls could both fall back to genesis and
	// both INSERT. Take the session-constant advisory lock first to close
	// that gap too — see AcquireAuditChainLock.
	if err := e.q.AcquireAuditChainLock(e.ctx); err != nil {
		return fmt.Errorf("auditchain: acquire chain lock: %w", err)
	}

	// First-ever row: sqlc returns pgx.ErrNoRows on the :one query when the
	// table is empty — that is the genesis case (substitute the all-zero
	// sentinel). A hand-edited generated file used to return (nil, nil), so
	// also accept (nil, nil) for resilience to whichever sqlc shape lands.
	// Any OTHER error is a real fetch failure and propagates.
	prevHash, err := e.q.LatestEntryHash(e.ctx)
	switch {
	case errors.Is(err, pgx.ErrNoRows), err == nil && prevHash == nil:
		genesis := make([]byte, 32)
		prevHash = genesis
	case err != nil:
		return fmt.Errorf("auditchain: fetch prev_hash: %w", err)
	}

	// 2. Build canonical payload JSON.
	fromOrg := ""
	if params.ActorOrgID != nil {
		fromOrg = *params.ActorOrgID
	}
	toOrg := ""
	if params.TargetOrgID != nil {
		toOrg = *params.TargetOrgID
	}
	payload := SwitchPayload{
		ActorUserID: params.ActorUserID,
		FromOrgID:   fromOrg,
		ToOrgID:     toOrg,
		RequestID:   params.RequestID,
		IP:          params.IP,
		UserAgent:   params.UserAgent,
	}
	payloadBytes, err := CanonicalPayload(payload)
	if err != nil {
		return err
	}

	// 3. Compute entry_hash.
	entryHash := ComputeHash(e.key, prevHash, payloadBytes)

	// 4. Parse actor UUID.
	actorUUID, err := uuid.Parse(params.ActorUserID)
	if err != nil {
		return fmt.Errorf("auditchain: actor_user_id is not a valid UUID: %w", err)
	}

	// 5. Parse optional org UUIDs.
	var actorOrgID *uuid.UUID
	if params.ActorOrgID != nil && *params.ActorOrgID != "" {
		parsed, perr := uuid.Parse(*params.ActorOrgID)
		if perr != nil {
			return fmt.Errorf("auditchain: actor_org_id is not a valid UUID: %w", perr)
		}
		actorOrgID = &parsed
	}

	var targetOrgID *uuid.UUID
	if params.TargetOrgID != nil && *params.TargetOrgID != "" {
		parsed, perr := uuid.Parse(*params.TargetOrgID)
		if perr != nil {
			return fmt.Errorf("auditchain: target_org_id is not a valid UUID: %w", perr)
		}
		targetOrgID = &parsed
	}

	// 6. Insert the row.
	_, err = e.q.EnqueueAuditEvent(e.ctx, shelldb.EnqueueAuditEventParams{
		EventType:   "auth.session_tenant_switched",
		ActorUserID: actorUUID,
		ActorOrgID:  actorOrgID,
		TargetOrgID: targetOrgID,
		RequestID:   params.RequestID,
		Payload:     payloadBytes,
		PrevHash:    prevHash,
		EntryHash:   entryHash,
	})
	if err != nil {
		return fmt.Errorf("auditchain: enqueue audit event (hash=%s): %w",
			hex.EncodeToString(entryHash), err)
	}
	return nil
}


