// ---------------------------------------------------------------------------
// fakeDBTX — satisfies shelldb.DBTX without touching Postgres.
// We need to exercise chainEnqueuer.Enqueue, which uses shelldb.Queries
// (a *Queries wrapping a DBTX). We pass a fakeDBTX to shelldb.New(…) in
// newFakeChainEnqueuer so the Queries struct is real but dispatches to our
// fake.
// ---------------------------------------------------------------------------

// fakeDBTX implements shelldb.DBTX via a narrow recording shim.
// Each query is matched by the query string prefix so fakes can intercept
// LatestEntryHash and EnqueueAuditEvent independently.
type fakeDBTX struct {
	// latestHash is returned by QueryRow when "SELECT entry_hash" is called.
	// nil → empty table (pgx.ErrNoRows returned from Scan).
	latestHash []byte
	latestErr  error // if non-nil, Scan returns this error instead

	// enqueueErr is returned by QueryRow when "INSERT INTO shell_bff" is called.
	enqueueErr error

	// captured is populated when EnqueueAuditEvent executes successfully.
	captured *shelldb.EnqueueAuditEventParams
}

// --- pgx.Row adapters -------------------------------------------------------

type fakeRow struct {
	scanFn func(dest ...any) error
}

func (r *fakeRow) Scan(dest ...any) error { return r.scanFn(dest...) }

// --- pgconn shim ------------------------------------------------------------

// pgconn.CommandTag is a value type; we return zero value from Exec.

// QueryRow dispatches to either the LatestEntryHash or EnqueueAuditEvent
// branch depending on which SQL constant the Queries struct is executing.
// The sqlc-generated constants are multi-line raw strings starting with
// "-- name: <QueryName>". We match by inspecting the name comment.
func (f *fakeDBTX) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	// LatestEntryHash — comment contains "LatestEntryHash"
	if strings.Contains(sql, "LatestEntryHash") {
		if f.latestErr != nil {
			return &fakeRow{scanFn: func(dest ...any) error { return f.latestErr }}
		}
		if f.latestHash == nil {
			return &fakeRow{scanFn: func(dest ...any) error { return pgx.ErrNoRows }}
		}
		return &fakeRow{scanFn: func(dest ...any) error {
			if len(dest) == 0 {
				return nil
			}
			ptr, ok := dest[0].(*[]byte)
			if !ok {
				return errors.New("fakeDBTX: expected *[]byte for entry_hash")
			}
			*ptr = f.latestHash
			return nil
		}}
	}

	// EnqueueAuditEvent — "INSERT INTO shell_bff"
	if f.enqueueErr != nil {
		return &fakeRow{scanFn: func(dest ...any) error { return f.enqueueErr }}
	}
	// Parse the args back to capture the params for assertion.
	if len(args) >= 8 {
		actorUserID, _ := args[1].(uuid.UUID)
		var actorOrgID *uuid.UUID
		if v, ok := args[2].(*uuid.UUID); ok {
			actorOrgID = v
		}
		var targetOrgID *uuid.UUID
		if v, ok := args[3].(*uuid.UUID); ok {
			targetOrgID = v
		}
		requestID, _ := args[4].(string)
		payload, _ := args[5].([]byte)
		prevHash, _ := args[6].([]byte)
		entryHash, _ := args[7].([]byte)
		f.captured = &shelldb.EnqueueAuditEventParams{
			EventType:   "auth.session_tenant_switched",
			ActorUserID: actorUserID,
			ActorOrgID:  actorOrgID,
			TargetOrgID: targetOrgID,
			RequestID:   requestID,
			Payload:     payload,
			PrevHash:    prevHash,
			EntryHash:   entryHash,
		}
	}
	// Return a successful row scan (the function returns ShellBffAuditOutbox).
	row := shelldb.ShellBffAuditOutbox{
		ID: uuid.New(),
	}
	return &fakeRow{scanFn: func(dest ...any) error {
		if len(dest) < 11 {
			return nil
		}
		if p, ok := dest[0].(*uuid.UUID); ok {
			*p = row.ID
		}
		return nil
	}}
}

