	prevHashBytes := bytes.Repeat([]byte{0xaa}, 32)
	fake := &fakeDBTX{latestHash: prevHashBytes}
	key := []byte("test-hmac-key-at-least-32-bytes!")
	e := newFakeChainEnqueuer(t, fake, key, "key-1")

