package auditchain

import (
	"context"
	"encoding/hex"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"

	shelldb "github.com/zenithflowinc/omnicore-platform/services/shell-bff/internal/db"
)

const (
	// NATSSubject is the NATS JetStream subject for workspace-switch audit events.
	// Audit subjects follow the pattern "audit.<context>.<action>".
	NATSSubject = "audit.auth.session_tenant_switched"

	// drainBatchSize is the maximum number of events claimed per tick.
	drainBatchSize = 100

	// maxPublishErrors is the number of consecutive publish errors at which
	// the drain relay stops working the current batch and waits for the
	// next tick, instead of burning through the rest of a batch that is
	// very likely all failing for the same reason (e.g. NATS is down). Each
	// failure still logs and leaves its row undrained for retry; hitting the
	// cap logs once more and aborts the remainder of THIS batch — it does
	// not skip or drop any row permanently. A successful publish resets the
	// counter, so one bad row among many healthy ones never trips this.
	maxPublishErrors = 10
)

// DrainDB is the minimal pool interface DrainRelay needs to open a
// transaction per drain batch. *platform/libs/go/db.Pool (embedding
// *pgxpool.Pool) satisfies this directly via pgxpool.Pool.BeginTx.
type DrainDB interface {
	BeginTx(ctx context.Context, opts pgx.TxOptions) (pgx.Tx, error)
}

// DrainRelay polls shell_bff.audit_outbox for undrained rows and publishes
// each one to NATS JetStream with Nats-Msg-Id set to the hex-encoded
// entry_hash (dedup). On successful publish, MarkEventDrained is called in
// the same transaction that claimed the row.
//
// The relay wakes every PollInterval (default 200ms). On NATS error,
// the row is left undrained and retried on the next tick. A consecutive
// error counter per run prevents a single persistently-failing run from
// burning through the whole batch (capped at maxPublishErrors).
//
// Shut down by cancelling the context passed to Run. The relay finishes
// the current batch before returning.
type DrainRelay struct {
	db           DrainDB
	js           jetstream.Publisher // narrowed from JetStream for testability
	pollInterval time.Duration
	logger       *slog.Logger
}

// NewDrainRelay constructs a DrainRelay. db opens a fresh transaction for
// every drain tick (see drainOnce) — the SELECT ... FOR UPDATE SKIP LOCKED
// in ListUndrainedEvents only excludes concurrently-claimed rows from
// ANOTHER replica's in-flight tx for as long as this tx stays open, so the
// whole claim-publish-mark cycle for a batch must share one transaction.
// pollInterval is configurable; pass 0 for the 200ms default.
//
// js accepts any jetstream.Publisher (jetstream.JetStream satisfies this
// interface). The narrower type makes unit testing possible without satisfying
// the full 36-method JetStream interface.
func NewDrainRelay(db DrainDB, js jetstream.Publisher, pollInterval time.Duration, logger *slog.Logger) *DrainRelay {
	if pollInterval <= 0 {
		pollInterval = 200 * time.Millisecond
	}
	if logger == nil {
		logger = slog.Default()
	}
	return &DrainRelay{
		db:           db,
		js:           js,
		pollInterval: pollInterval,
		logger:       logger,
	}
}

// Run starts the drain loop. It blocks until ctx is cancelled, at which
// point it finishes the current batch and returns ctx.Err().
func (d *DrainRelay) Run(ctx context.Context) error {
	ticker := time.NewTicker(d.pollInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			// Drain one final batch before exiting.
			d.drainOnce(ctx)
			return ctx.Err()
		case <-ticker.C:
			d.drainOnce(ctx)
		}
	}
}

// drainOnce fetches up to drainBatchSize undrained rows and publishes each
// to NATS. Errors are logged and skipped — the relay is designed to never
// block on a single bad row.
//
// P1-28: the claim (SELECT ... FOR UPDATE SKIP LOCKED) and the marks
// (UPDATE ... SET drained_at) run inside one transaction, held open for the
// whole batch. Without an explicit transaction, pgx auto-commits each
// statement individually, so the row locks from FOR UPDATE would be
// released the instant the SELECT returned — before this replica finishes
// publishing — and SKIP LOCKED on a second, concurrently-running replica
// would guard nothing, letting both replicas claim and publish the same
// rows. The transaction commits at the end regardless of individual
// publish outcomes: only successfully-published rows get MarkEventDrained,
// so a commit persists exactly the marks this batch actually earned.
func (d *DrainRelay) drainOnce(ctx context.Context) {
	tx, err := d.db.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		d.logger.ErrorContext(ctx, "auditchain drain: BeginTx", "err", err)
		return
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := shelldb.New(tx)

	rows, err := q.ListUndrainedEvents(ctx, drainBatchSize)
	if err != nil {
		d.logger.ErrorContext(ctx, "auditchain drain: ListUndrainedEvents", "err", err)
		return
	}

	// consecutivePublishErrors resets to 0 on every successful publish, so
	// only a run of back-to-back failures (not scattered ones) trips the
	// maxPublishErrors abort below.
	consecutivePublishErrors := 0

	for i, row := range rows {
		msgID := hex.EncodeToString(row.EntryHash)

		msg := &nats.Msg{
			Subject: NATSSubject,
			Data:    row.Payload,
			Header:  nats.Header{},
		}
		msg.Header.Set("Nats-Msg-Id", msgID)
		msg.Header.Set("content-type", "application/json")

		if _, err := d.js.PublishMsg(ctx, msg); err != nil {
			consecutivePublishErrors++
			d.logger.ErrorContext(ctx, "auditchain drain: publish failed",
				"event_id", row.ID,
				"msg_id", msgID,
				"err", err,
				"consecutive_publish_errors", consecutivePublishErrors)
			// Leave row undrained; next tick will retry.
			if consecutivePublishErrors >= maxPublishErrors {
				d.logger.ErrorContext(ctx, "auditchain drain: max consecutive publish errors reached, "+
					"aborting rest of this batch (will retry next tick)",
					"max_publish_errors", maxPublishErrors,
					"rows_remaining", len(rows)-1-i)
				break
			}
			continue
		}
		consecutivePublishErrors = 0

		if err := q.MarkEventDrained(ctx, row.ID); err != nil {
			d.logger.ErrorContext(ctx, "auditchain drain: MarkEventDrained failed",
				"event_id", row.ID,
				"err", err)
			// Row was published but not marked. The Nats-Msg-Id dedup header
			// ensures a second publish is idempotent; the next tick will
			// re-publish and re-attempt MarkEventDrained.
		}
	}

	if err := tx.Commit(ctx); err != nil {
		d.logger.ErrorContext(ctx, "auditchain drain: commit failed", "err", err)
	}
}


