// Package auditchain — unit tests for DrainRelay.
package auditchain

import (
	"context"
	"encoding/hex"
	"errors"
	"log/slog"
	"strings"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"github.com/stretchr/testify/require"

	shelldb "github.com/zenithflowinc/omnicore-platform/services/shell-bff/internal/db"
)

// ---------------------------------------------------------------------------
// drainFakeDBTX — DBTX for DrainRelay (ListUndrainedEvents + MarkEventDrained)
//
// ListUndrainedEvents uses Query; MarkEventDrained uses Exec.
// The SQL comment dispatching used in chain_enqueuer_test.go applies here too.
// ---------------------------------------------------------------------------

type drainFakeDBTX struct {
	rows     []shelldb.ShellBffAuditOutbox
	listErr  error
	drainErr error

	// DrainedIDs accumulates every ID passed to MarkEventDrained.
	DrainedIDs []uuid.UUID
}

// QueryRow is not used by DrainRelay; stub that returns an error.
func (f *drainFakeDBTX) QueryRow(ctx context.Context, sql string, args ...any) pgx.Row {
	return &fakeRow{scanFn: func(d ...any) error {
		return errors.New("drainFakeDBTX: unexpected QueryRow call")
	}}
}

// drainFakeRows implements pgx.Rows for ListUndrainedEvents.
// The sqlc-generated code calls rows.Next(), rows.Scan(...), rows.Close(), rows.Err().
type drainFakeRows struct {
	items []shelldb.ShellBffAuditOutbox
	idx   int
}

func (r *drainFakeRows) Next() bool                                   { return r.idx < len(r.items) }
func (r *drainFakeRows) Err() error                                   { return nil }
func (r *drainFakeRows) Close()                                       {}
func (r *drainFakeRows) CommandTag() pgconn.CommandTag                { return pgconn.CommandTag{} }
func (r *drainFakeRows) FieldDescriptions() []pgconn.FieldDescription { return nil }
func (r *drainFakeRows) RawValues() [][]byte                          { return nil }
func (r *drainFakeRows) Values() ([]any, error)                       { return nil, nil }
func (r *drainFakeRows) Conn() *pgx.Conn                              { return nil }

// compile-time check: drainFakeRows satisfies pgx.Rows.
var _ pgx.Rows = (*drainFakeRows)(nil)

func (r *drainFakeRows) Scan(dest ...any) error {
	if r.idx >= len(r.items) {
		return errors.New("drainFakeRows: no more rows")
	}
	row := r.items[r.idx]
	r.idx++
	// Scan order matches ListUndrainedEvents column list in queries.sql.go:
	// id, event_type, actor_user_id, actor_org_id, target_org_id,
	// request_id, payload, prev_hash, entry_hash, created_at, drained_at
	if len(dest) < 11 {
		return errors.New("drainFakeRows: need 11 destinations")
	}
	assign(dest[0], row.ID)
	assign(dest[1], row.EventType)
	assign(dest[2], row.ActorUserID)
	assignOptUUID(dest[3], row.ActorOrgID)
	assignOptUUID(dest[4], row.TargetOrgID)
	assign(dest[5], row.RequestID)
	assign(dest[6], row.Payload)
	assign(dest[7], row.PrevHash)
	assign(dest[8], row.EntryHash)
	assign(dest[9], row.CreatedAt)
	assign(dest[10], row.DrainedAt)
	return nil
}

func assign(dest any, val any) {
	switch d := dest.(type) {
	case *uuid.UUID:
		if v, ok := val.(uuid.UUID); ok {
			*d = v
		}
	case *string:
		if v, ok := val.(string); ok {
			*d = v
		}
	case *[]byte:
		if v, ok := val.([]byte); ok {
			*d = v
		}
	case *pgtype.Timestamptz:
		if v, ok := val.(pgtype.Timestamptz); ok {
			*d = v
		}
	}
}

func assignOptUUID(dest any, val *uuid.UUID) {
	if d, ok := dest.(**uuid.UUID); ok {
		*d = val
	}
}

