// TestDrainRelay_DrainOnce_TwoRows_PublishesWithMsgID asserts that:
//   - each row's payload is published to NATSSubject
//   - Nats-Msg-Id header equals hex(entry_hash) for that row
//   - MarkEventDrained is called for each row in order
func TestDrainRelay_DrainOnce_TwoRows_PublishesWithMsgID(t *testing.T) {
	hash1 := []byte("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa1")
	hash2 := []byte("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa2")
	payload1 := []byte(`{"event":"first"}`)
	payload2 := []byte(`{"event":"second"}`)

	row1 := sampleRow(payload1, hash1)
	row2 := sampleRow(payload2, hash2)

	fake := &drainFakeDBTX{rows: []shelldb.ShellBffAuditOutbox{row1, row2}}
	pub := &fakePublisher{}
	relay := newTestRelay(t, fake, pub)

	relay.drainOnce(context.Background())

	require.Len(t, pub.published, 2)
	require.Len(t, fake.DrainedIDs, 2)

	// Check row1.
	msg1 := pub.published[0]
	require.Equal(t, NATSSubject, msg1.Subject)
	require.Equal(t, payload1, msg1.Data)
	require.Equal(t, hex.EncodeToString(hash1), msg1.Header.Get("Nats-Msg-Id"))

	// Check row2.
	msg2 := pub.published[1]
	require.Equal(t, NATSSubject, msg2.Subject)
	require.Equal(t, payload2, msg2.Data)
	require.Equal(t, hex.EncodeToString(hash2), msg2.Header.Get("Nats-Msg-Id"))

	// MarkEventDrained called for both rows.
	require.Equal(t, row1.ID, fake.DrainedIDs[0])
	require.Equal(t, row2.ID, fake.DrainedIDs[1])
}

